CREATE OR REPLACE FUNCTION public.fn_upsert_tournament_schedule(p_schedule jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_id        uuid;
  v_union_id  uuid;
  v_club_id   uuid;
  v_name      text;
  v_days      integer[];
  v_times     text[];
  v_interval  integer;
  v_config    jsonb;
  v_active    boolean;
  v_zone      text;
  v_d         integer;
  v_tm        text;
  v_existing  record;
  v_config_changed boolean := true;
  v_refusal   text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;
  IF p_schedule IS NULL OR jsonb_typeof(p_schedule) <> 'object' THEN
    RETURN jsonb_build_object('error', 'schedule_must_be_object');
  END IF;

  v_id       := NULLIF(p_schedule->>'id', '')::uuid;
  v_union_id := NULLIF(p_schedule->>'unionId', '')::uuid;
  v_club_id  := NULLIF(p_schedule->>'clubId', '')::uuid;
  v_name     := NULLIF(trim(p_schedule->>'name'), '');
  v_interval := NULLIF(p_schedule->>'intervalMinutes', '')::integer;
  v_config   := p_schedule->'config';
  v_active   := COALESCE((p_schedule->>'active')::boolean, true);
  -- IANA zone of the wall-clock days/times; absent or null = UTC.
  v_zone     := NULLIF(trim(p_schedule->>'timeZone'), '');

  SELECT COALESCE(array_agg(value::integer), '{}')
    INTO v_days FROM jsonb_array_elements_text(COALESCE(p_schedule->'daysOfWeek', '[]'::jsonb));
  SELECT COALESCE(array_agg(value), '{}')
    INTO v_times FROM jsonb_array_elements_text(COALESCE(p_schedule->'startTimesUtc', '[]'::jsonb));

  IF v_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.tournament_schedules WHERE id = v_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'schedule_not_found');
    END IF;
    IF NOT public.fn_can_manage_tournament_schedule(v_existing.union_id, v_existing.club_id, v_uid) THEN
      RETURN jsonb_build_object('error', 'not_authorised');
    END IF;
    v_union_id := COALESCE(v_union_id, v_existing.union_id);
    v_club_id  := COALESCE(v_club_id,  v_existing.club_id);
    v_name     := COALESCE(v_name,     v_existing.name);
    v_config   := COALESCE(v_config,   v_existing.config);
    v_config_changed := v_config IS DISTINCT FROM v_existing.config;
    IF p_schedule->'daysOfWeek' IS NULL THEN v_days := v_existing.days_of_week; END IF;
    IF p_schedule->'startTimesUtc' IS NULL THEN v_times := v_existing.start_times_utc; END IF;
    IF p_schedule->'intervalMinutes' IS NULL THEN v_interval := v_existing.interval_minutes; END IF;
    IF NOT (p_schedule ? 'timeZone') THEN v_zone := v_existing.time_zone; END IF;
  END IF;

  IF v_club_id IS NULL THEN
    RETURN jsonb_build_object('error', 'club_id_required');
  END IF;
  IF v_name IS NULL THEN
    RETURN jsonb_build_object('error', 'name_required');
  END IF;
  IF v_config IS NULL OR jsonb_typeof(v_config) <> 'object' THEN
    RETURN jsonb_build_object('error', 'config_must_be_object');
  END IF;
  IF array_length(v_days, 1) IS NULL THEN
    RETURN jsonb_build_object('error', 'days_of_week_required');
  END IF;
  FOREACH v_d IN ARRAY v_days LOOP
    IF v_d < 0 OR v_d > 6 THEN
      RETURN jsonb_build_object('error', 'days_of_week_out_of_range', 'detail', v_d);
    END IF;
  END LOOP;
  FOREACH v_tm IN ARRAY v_times LOOP
    IF v_tm !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RETURN jsonb_build_object('error', 'start_time_format_invalid', 'detail', v_tm);
    END IF;
  END LOOP;
  IF array_length(v_times, 1) IS NULL AND v_interval IS NULL THEN
    RETURN jsonb_build_object('error', 'start_times_or_interval_required');
  END IF;
  IF v_interval IS NOT NULL AND (v_interval < 5 OR v_interval > 1440) THEN
    RETURN jsonb_build_object('error', 'interval_minutes_out_of_range');
  END IF;
  IF NOT public.fn_schedule_time_zone_is_known(v_zone) THEN
    RETURN jsonb_build_object('error', 'time_zone_unknown', 'detail', v_zone);
  END IF;

  IF v_id IS NULL AND NOT public.fn_can_manage_tournament_schedule(v_union_id, v_club_id, v_uid) THEN
    RETURN jsonb_build_object('error', 'not_authorised');
  END IF;
  -- Lock/read comparison preserves unchanged accepted schedules, including
  -- enable/disable and metadata edits, without authoring another ignored break.
  IF v_config_changed AND (
    lower(COALESCE(v_config->>'type','mtt')) NOT IN ('sng','spin')
    -- The scheduled writer promotes target-linked fixed labels to satellites.
    -- Only its recognized target keys participate; unrelated type aliases do not.
    OR public.fn_ca_is_new_mtt(jsonb_build_object(
      'satellite_target_id',v_config->'satellite_target_id',
      'satelliteTargetId',v_config->'satelliteTargetId',
      'satellite_target',v_config->'satellite_target',
      'satelliteTarget',v_config->'satelliteTarget'))
  ) AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(CASE
      WHEN jsonb_typeof(v_config->'blindStructure')='array' THEN v_config->'blindStructure'
      ELSE '[]'::jsonb END) AS level_row
    WHERE level_row->'isBreak'='true'::jsonb
  ) THEN
    RETURN jsonb_build_object('error','custom_level_breaks_not_supported');
  END IF;

  -- The creation rules, checked when the configuration is written rather than
  -- first discovered by the spawner (20260924033701).
  IF v_config_changed THEN
    v_refusal := public.fn_tournament_config_refusal(v_config,'schedule');
    IF v_refusal IS NOT NULL THEN
      RETURN jsonb_build_object('error',v_refusal);
    END IF;
  END IF;

  IF v_id IS NULL THEN
    -- ca-commerce-admission: a NEW recurring schedule is a prospective owner
    -- action (R2 4.3, D22). Shadow records and proceeds; enforced refuses
    -- here, before the schedule is written.
    DECLARE
      v_ca_admission jsonb := public.fn_ca_commerce_admit('club', v_club_id, 'create_tournament', 'fn_upsert_tournament_schedule', NULL);
    BEGIN
      IF NOT COALESCE((v_ca_admission->>'allowed')::boolean, true) THEN
        RETURN jsonb_build_object('error', 'operating_access_required',
          'message', v_ca_admission->>'message', 'reason', v_ca_admission->>'reason');
      END IF;
    END;
    INSERT INTO public.tournament_schedules
      (union_id, club_id, name, description, active, days_of_week,
       start_times_utc, interval_minutes, config, created_by, time_zone)
    VALUES
      (v_union_id, v_club_id, v_name, p_schedule->>'description', v_active, v_days,
       v_times, v_interval, v_config, v_uid, v_zone)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.tournament_schedules
       SET union_id         = v_union_id,
           club_id          = v_club_id,
           name             = v_name,
           description      = COALESCE(p_schedule->>'description', description),
           active           = v_active,
           days_of_week     = v_days,
           start_times_utc  = v_times,
           interval_minutes = v_interval,
           config           = v_config,
           time_zone        = v_zone,
           updated_at       = now()
     WHERE id = v_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'schedule_id', v_id);
END; $function$

CREATE OR REPLACE FUNCTION public.fn_tournament_config_refusal(p_config jsonb, p_surface text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_schedule boolean;
  v_type     text;
  v_short    boolean;
  v_stack    numeric;
  v_start    timestamptz;
  v_target   jsonb;
  v_ok       boolean;
  v_total    numeric;
  v_level    jsonb;
  v_sb       numeric;
  v_bb       numeric;
  v_prev_sb  numeric;
  v_prev_bb  numeric;
  v_seen     boolean := false;
  v_variant  text;
  v_hole     int;
  v_deck     int;
  v_seats    numeric;
  v_rebuy    boolean;
  v_late     numeric;
  v_late_min numeric;
  v_buy_in   numeric;
BEGIN
  IF p_surface IS NULL OR p_surface NOT IN ('create', 'schedule') THEN
    RAISE EXCEPTION 'fn_tournament_config_refusal: unknown surface %', p_surface
      USING ERRCODE = '22023';
  END IF;
  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RETURN 'invalid_configuration';
  END IF;
  v_schedule := p_surface = 'schedule';

  BEGIN
    v_type := lower(COALESCE(NULLIF(btrim(p_config->>'type'), ''), 'mtt'));
    IF v_schedule AND v_type IN ('hu_sng', 'heads_up') THEN v_type := 'sng'; END IF;
    v_short := v_type IN ('sng', 'spin');

    -- 1. Starting stack: a whole number above zero, for every format.
    v_stack := NULLIF(p_config->>'startingStack', '')::numeric;
    IF v_stack IS NOT NULL AND (v_stack <= 0 OR v_stack <> trunc(v_stack)) THEN
      RETURN 'starting_stack_must_be_positive';
    END IF;

    -- 2. A start in the past is refused, never silently moved. Five minutes of
    --    skew for a device clock that runs slow.
    IF NOT v_schedule THEN
      v_start := NULLIF(p_config->>'startTime', '')::timestamptz;
      IF v_start IS NOT NULL AND v_start < now() - interval '5 minutes' THEN
        RETURN 'start_time_in_past';
      END IF;
    END IF;

    -- 3. A satellite names the event its seats go into.
    IF v_type = 'satellite' THEN
      IF v_schedule THEN
        v_target := COALESCE(p_config->'satelliteTarget', p_config->'satellite_target');
        -- COALESCE: with no target object every jsonb_typeof test is NULL, and
        -- NOT NULL would wave the satellite through.
        v_ok := COALESCE(
                (jsonb_typeof(v_target) = 'string' AND btrim(v_target #>> '{}') <> '')
             OR (jsonb_typeof(v_target) = 'object'
                 AND COALESCE(NULLIF(v_target->>'tournamentId', ''), NULLIF(v_target->>'tournament_id', '')) IS NOT NULL),
                false)
             OR COALESCE(btrim(p_config->>'satelliteTargetId'), '') <> ''
             OR COALESCE(btrim(p_config->>'satellite_target_id'), '') <> ''
             OR COALESCE(btrim(p_config->>'satelliteTargetName'), '') <> '';
      ELSE
        v_ok := COALESCE(btrim(p_config->>'satelliteTargetId'), '') <> '';
      END IF;
      IF NOT v_ok THEN
        RETURN 'satellite_target_required';
      END IF;
    END IF;

    -- 4. Payouts add up to 100, within the governed creator's tolerance of 1.
    IF jsonb_typeof(p_config->'payoutStructure') = 'array'
       AND jsonb_array_length(p_config->'payoutStructure') > 0 THEN
      SELECT COALESCE(SUM((e->>'percentage')::numeric), 0) INTO v_total
        FROM jsonb_array_elements(p_config->'payoutStructure') e;
      IF abs(v_total - 100) > 1 THEN
        RETURN 'payouts_must_total_100';
      END IF;
    END IF;

    -- 5. A Sit And Go or Spin ladder: positive durations, blinds never fall.
    --    Break rows (a flag, or 0/0 blinds) do not take part. A new MTT ladder
    --    is held to the fuller contract by tournaments_new_mtt_blind_contract.
    IF v_short AND jsonb_typeof(p_config->'blindStructure') = 'array' THEN
      FOR v_level IN SELECT value FROM jsonb_array_elements(p_config->'blindStructure') LOOP
        IF jsonb_typeof(v_level) <> 'object' THEN
          RETURN 'invalid_configuration';
        END IF;
        IF NULLIF(v_level->>'durationMinutes', '') IS NOT NULL
           AND (v_level->>'durationMinutes')::numeric <= 0 THEN
          RETURN 'blind_level_duration_invalid';
        END IF;
        v_sb := NULLIF(v_level->>'smallBlind', '')::numeric;
        v_bb := NULLIF(v_level->>'bigBlind', '')::numeric;
        CONTINUE WHEN COALESCE(v_level->>'isBreak', '') = 'true' OR (v_sb = 0 AND v_bb = 0);
        IF v_seen AND (v_sb < v_prev_sb OR v_bb < v_prev_bb) THEN
          RETURN 'blind_structure_must_not_decrease';
        END IF;
        v_prev_sb := v_sb;
        v_prev_bb := v_bb;
        v_seen := true;
      END LOOP;
    END IF;

    -- 6. No more seats at a table than one deck can deal: the deck, less one
    --    board, over the hole cards each seat takes (VariantRules.maxSeatsFor).
    v_variant := lower(btrim(COALESCE(p_config->>'gameVariant', 'NLH')));
    v_hole := CASE
      WHEN v_variant IN ('plo4', 'plo8', 'flo8') THEN 4
      WHEN v_variant = 'plo5' THEN 5
      WHEN v_variant = 'plo6' THEN 6
      WHEN v_variant = 'pineapple' THEN 3
      ELSE 2 END;
    v_deck := CASE WHEN v_variant LIKE 'short%' THEN 36 ELSE 52 END;
    IF v_schedule AND v_type = 'spin' THEN
      v_seats := 3;
    ELSE
      v_seats := round(NULLIF(p_config->>'tableSize', '')::numeric);
      IF v_seats IS NULL THEN
        v_seats := CASE
          WHEN v_schedule AND v_short
            THEN COALESCE(round(NULLIF(p_config->>'maxPlayers', '')::numeric), 2)
          ELSE 9 END;
      END IF;
      v_seats := LEAST(10, GREATEST(2, v_seats));
    END IF;
    IF v_seats > (v_deck - 5) / v_hole THEN
      RETURN 'table_size_exceeds_deck';
    END IF;

    -- 7. A rebuy or re-entry needs a late registration window to be sold in.
    IF v_schedule THEN
      v_rebuy := COALESCE(p_config->>'isRebuy', '') = 'true'
              OR COALESCE(p_config->>'rebuy', '') = 'true'
              OR COALESCE(p_config->>'isReentry', '') = 'true'
              OR v_type IN ('rebuy', 'reentry', 'mtt_rebuy', 'mtt_reentry');
      v_late := CASE
        WHEN v_short THEN 0
        WHEN NOT (p_config ? 'lateRegistrationLevels') THEN 8
        ELSE COALESCE(NULLIF(p_config->>'lateRegistrationLevels', '')::numeric, 0) END;
      v_late_min := 0;
    ELSE
      v_rebuy := COALESCE((p_config->>'isRebuy')::boolean, false)
              OR COALESCE((p_config->>'isReentry')::boolean, false);
      v_late := CASE WHEN v_short THEN 0
        ELSE COALESCE(NULLIF(p_config->>'lateRegistrationLevels', '')::numeric, 0) END;
      v_late_min := COALESCE(NULLIF(p_config->>'lateRegistrationMinutes', '')::numeric, 0);
    END IF;
    v_buy_in := COALESCE(NULLIF(p_config->>'buyIn', '')::numeric, 0);
    IF v_rebuy
       AND NOT (v_buy_in = 0 AND NOT v_short)   -- a Free Buy event has its own levels
       AND v_late <= 0 AND v_late_min <= 0 THEN
      RETURN 'rebuy_requires_late_registration';
    END IF;
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range
      OR invalid_datetime_format OR datetime_field_overflow THEN
      RETURN 'invalid_configuration';
  END;

  RETURN NULL;
END;
$function$

